import{_ as e,c as o,o as d,ag as a}from"./chunks/framework.3IuuWm4t.js";const g=JSON.parse('{"title":"Astro 配置指南","description":"","frontmatter":{},"headers":[],"relativePath":"platforms/github-astro.md","filePath":"platforms/github-astro.md","lastUpdated":1795809563000}'),s={name:"platforms/github-astro.md"};function r(i,t,c,l,n,h){return d(),o("div",null,[...t[0]||(t[0]=[a(`<h1 id="astro-配置指南" tabindex="-1">Astro 配置指南 <a class="header-anchor" href="#astro-配置指南" aria-label="Permalink to &quot;Astro 配置指南&quot;">​</a></h1><p>通过 <strong>GitHub API</strong> 将文章发布到 <strong>Astro</strong> 站点仓库。</p><h2 id="一、准备" tabindex="-1">一、准备 <a class="header-anchor" href="#一、准备" aria-label="Permalink to &quot;一、准备&quot;">​</a></h2><ol><li>一个可作为 Astro 站点的 <strong>GitHub 仓库</strong>（如 <code>astro-blog</code>，博客文章放在 <code>src/content/blog</code> 下）。</li><li>一个对该仓库有 <strong>push 权限</strong> 的 <strong>GitHub Token（PAT）</strong>（GitHub Settings → Developer settings → Personal access tokens，勾选 <code>repo</code> 权限）。</li><li>站点仓库已配置构建部署（例如 Vercel / GitHub Actions / Netlify），推送 <code>.md</code> 后能触发重新构建上线。</li></ol><h2 id="二、配置" tabindex="-1">二、配置 <a class="header-anchor" href="#二、配置" aria-label="Permalink to &quot;二、配置&quot;">​</a></h2><table tabindex="0"><thead><tr><th>字段</th><th>填什么</th></tr></thead><tbody><tr><td>首页地址</td><td>GitHub 首页地址，默认 <code>https://github.com</code></td></tr><tr><td>API 地址</td><td>GitHub API 地址，默认 <code>https://api.github.com</code>，通常无需修改</td></tr><tr><td>用户名</td><td>GitHub 用户名（owner），用于拼出仓库地址</td></tr><tr><td>鉴权 Token</td><td>GitHub 个人访问令牌（PAT），需对目标仓库有 push 权限</td></tr><tr><td>git 仓库名</td><td>站点仓库名（裸仓库名，不带 <code>owner/</code> 前缀），例如 <code>astro-blog</code></td></tr><tr><td>默认分支</td><td>发布到的分支，默认 <code>main</code></td></tr><tr><td>存储目录</td><td>文章存储目录，默认 <code>src/content/blog</code>（Astro 内容集合目录）。发布后的 <code>.md</code> 会写入该目录</td></tr><tr><td>文件规则</td><td>文章文件名规则，默认 <code>[slug].md</code>（文章别名）</td></tr><tr><td>文章预览规则</td><td>站点文章预览规则，默认 <code>/post/[postid].html</code>（Astro 按文件路径生成路由，实际地址由文件路径决定，此规则仅作查看参考）</td></tr><tr><td>预览规则</td><td>GitHub blob 预览规则，固定 <code>/[user]/[repo]/blob/[branch]/[docpath]</code>，不支持修改</td></tr><tr><td>图床</td><td>默认「当前平台」：图片上传到<strong>仓库根目录</strong>的 <code>public/images</code>，文章引用<strong>绝对路径</strong> <code>/images/&lt;图片名&gt;</code></td></tr></tbody></table><p>发布写入的 front matter 含 <code>title</code>、<code>description</code>、<code>pubDate</code>（<code>yyyy-MM-dd</code>）、<code>tags</code>、<code>categories</code>、<code>keywords</code>（可在「YAML 预设配置」中覆盖）。</p><h2 id="三、图片约定-astro-公共资源目录" tabindex="-1">三、图片约定（Astro 公共资源目录） <a class="header-anchor" href="#三、图片约定-astro-公共资源目录" aria-label="Permalink to &quot;三、图片约定（Astro 公共资源目录）&quot;">​</a></h2><ul><li>Astro 把 <code>public/</code> 下的资源<strong>原样拷贝</strong>到构建输出根目录，因此图片放 <code>public/images</code>，站点上即以 <code>/images/&lt;图片名&gt;</code> 访问。</li><li><code>imageStorePath = public/images</code> 是<strong>仓库根目录</strong>下的固定路径（不随文章目录变化）。</li><li><code>imageLinkPath = /images</code> 生成<strong>绝对路径</strong>引用 <code>/images/&lt;图片名&gt;</code>（绝对路径，不是相对资源的 <code>./images</code>）。</li><li>发布带图文章后，仓库中会出现 <code>.md</code> 与 <code>public/images/&lt;图片名&gt;</code>。</li></ul><h2 id="四、发布目录的限制" tabindex="-1">四、发布目录的限制 <a class="header-anchor" href="#四、发布目录的限制" aria-label="Permalink to &quot;四、发布目录的限制&quot;">​</a></h2><p>Astro 的发布目录固定为内容集合目录（默认 <code>src/content/blog</code>），<strong>配置页不提供修改</strong>（「发布目录」为只读提示）。如需更换位置，请在仓库中调整内容集合配置后重新发布。</p><h2 id="五、验证与发布" tabindex="-1">五、验证与发布 <a class="header-anchor" href="#五、验证与发布" aria-label="Permalink to &quot;五、验证与发布&quot;">​</a></h2><ol><li>点「验证」→ Token、仓库、分支校验通过 → 保持「配置已保存并验证通过」。</li><li>快速发布 → 选 Astro → 发布。文章 <code>.md</code> 提交到 <code>存储目录/[slug].md</code>。</li><li>「查看文章」打开仓库 blob 地址；站点线上地址由内容集合的文件路径决定，需站点已构建部署。</li><li>带图发布时图片上传到 <code>public/images</code>，文章引用 <code>/images/&lt;图片名&gt;</code>。</li></ol><h2 id="六、yaml-预设配置与占位符" tabindex="-1">六、YAML 预设配置与占位符 <a class="header-anchor" href="#六、yaml-预设配置与占位符" aria-label="Permalink to &quot;六、YAML 预设配置与占位符&quot;">​</a></h2><p>「YAML 预设配置」填一个 JSON 对象，首次生成该平台 YAML 时逐键合并进 Front Matter；同名键会覆盖插件自动生成的字段。取值支持占位符，按当前文章解析：</p><table tabindex="0"><thead><tr><th>占位符</th><th>含义</th><th>示例</th></tr></thead><tbody><tr><td><code>[createDate-格式]</code></td><td>文章创建时间；格式为日期格式串，省略时 <code>YYYY-MM-DD</code></td><td><code>[createDate-YYYY-MM-DD]</code>、<code>[createDate-YYYY-MM-DD HH:mm:ss]</code></td></tr><tr><td><code>[updateDate-格式]</code></td><td>文章更新时间；没有更新时间时用创建时间</td><td><code>[updateDate-YYYY-MM-DD]</code></td></tr><tr><td><code>[tags]</code></td><td>标签</td><td><code>[tags]</code></td></tr><tr><td><code>[categories]</code></td><td>分类</td><td><code>[categories]</code></td></tr><tr><td><code>[title]</code></td><td>文章标题</td><td><code>[title]</code></td></tr><tr><td><code>[slug]</code></td><td>文章别名</td><td><code>[slug]</code></td></tr></tbody></table><p>整个值就是占位符时保留原生类型（<code>[tags]</code>、<code>[categories]</code> 输出 YAML 数组）；写在句子里时按文本替换（多个标签用逗号连接）。未知写法原样保留，不会被替换。</p><p>例如 Astro 内容集合需要 <code>updatedDate</code> 时：</p><div class="language-json vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;updatedDate&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;[createDate-YYYY-MM-DD]&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;author&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;terwer&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>配置必须是合法的 JSON 对象，保存时会校验；解析失败的配置不会再被静默忽略。</p><p>2.4.0 起，「YAML 预设配置」支持日期、标题、别名、标签与分类占位符；2.5.0 起支持 <code>[attr:属性名]</code> 文档属性占位符。预设仅在首次生成平台 YAML 时应用，已发布文章的更新沿用已保存的 YAML。完整语法与修改已有文章的方法见 <a href="/siyuan-plugin-publisher/guide/single-publish.html#yaml-预设配置">YAML 预设配置</a>。</p><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><ul><li><strong>验证通过但发布失败</strong>：确认 Token 对目标仓库有 push 权限、仓库名与分支正确。权限不足会收到 401/403。</li><li><strong>图片要怎么发布</strong>：图床默认「当前平台」，图片提交到仓库根目录的 <code>public/images</code>，文章引用绝对路径 <code>/images/&lt;图片名&gt;</code>。</li><li><strong>线上没有新文章</strong>：Astro 站点需要构建。确认仓库已绑定 Vercel / Actions 等自动构建；仅推送 <code>.md</code> 不会直接改变已部署站点。</li><li><strong>发布目录能不能改</strong>：不能，固定为内容集合目录；如需更换请在仓库中调整后重新发布。</li><li><strong>更新与删除</strong>：点「更新」会重新提交该文章并产生一次新提交；「删除」会移除仓库中对应的 <code>.md</code>，站点需重新构建才会同步下线。</li></ul>`,23)])])}const u=e(s,[["render",r]]);export{g as __pageData,u as default};
